const arRecords = new Map();
const bankRecords = new Map();

for (const item of items) {
  const data = item.json;
  const key = String(data.recon_key).trim();

  if (data.source === "AR Ledger") {
    if (!arRecords.has(key)) {
      arRecords.set(key, []);
    }
    arRecords.get(key).push(data);
  }

  if (data.source === "Bank Remittance") {
    if (!bankRecords.has(key)) {
      bankRecords.set(key, []);
    }
    bankRecords.get(key).push(data);
  }
}

const allKeys = new Set([
  ...arRecords.keys(),
  ...bankRecords.keys()
]);

const results = [];

for (const key of allKeys) {
  const ar = arRecords.get(key) || [];
  const bank = bankRecords.get(key) || [];

  results.push({
    json: {
      recon_key: key,

      exists_in_ar: ar.length > 0,
      exists_in_bank: bank.length > 0,

      ar_count: ar.length,
      bank_count: bank.length,

      ar_records: ar,
      bank_records: bank
    }
  });
}

return results;

const results = [];

for (const item of items) {
  const data = item.json;

  const existsInAR = data.exists_in_ar;
  const existsInBank = data.exists_in_bank;

  const arCount = data.ar_count;
  const bankCount = data.bank_count;

  // --------------------------------------------------
  // CASE 1: AR only
  // --------------------------------------------------
  if (existsInAR && !existsInBank) {
    results.push({
      json: {
        ...data,
        key_match: false,
        final_status: "EXCEPTION",
        exception_reason: "Transaction Present in AR Only",
        action: "For Investigation"
      }
    });

    continue;
  }

  // --------------------------------------------------
  // CASE 2: Bank only
  // --------------------------------------------------
  if (!existsInAR && existsInBank) {
    results.push({
      json: {
        ...data,
        key_match: false,
        final_status: "EXCEPTION",
        exception_reason: "Transaction Present in Bank Only",
        action: "For Investigation"
      }
    });

    continue;
  }

  // --------------------------------------------------
  // CASE 3: Duplicate in both sources
  // --------------------------------------------------
  if (arCount > 1 && bankCount > 1) {
    results.push({
      json: {
        ...data,
        key_match: true,
        duplicate_ar: true,
        duplicate_bank: true,
        final_status: "EXCEPTION",
        exception_reason: "Duplicate Entry in Both Sources",
        action: "For Investigation"
      }
    });

    continue;
  }

  // --------------------------------------------------
  // CASE 4: Duplicate AR
  // --------------------------------------------------
  if (arCount > 1 && bankCount === 1) {
    results.push({
      json: {
        ...data,
        key_match: true,
        duplicate_ar: true,
        duplicate_bank: false,
        final_status: "EXCEPTION",
        exception_reason: "Duplicate AR Entry",
        action: "For Investigation"
      }
    });

    continue;
  }

  // --------------------------------------------------
  // CASE 5: Duplicate Bank
  // --------------------------------------------------
  if (arCount === 1 && bankCount > 1) {
    results.push({
      json: {
        ...data,
        key_match: true,
        duplicate_ar: false,
        duplicate_bank: true,
        final_status: "EXCEPTION",
        exception_reason: "Duplicate Bank Entry",
        action: "For Investigation"
      }
    });

    continue;
  }

  // --------------------------------------------------
  // CASE 6: Clean 1-to-1 transaction
  // --------------------------------------------------
  if (
    arCount === 1 &&
    bankCount === 1 &&
    existsInAR &&
    existsInBank
  ) {
    const ar = data.ar_records[0];
    const bank = data.bank_records[0];

    // Amount
    const amount_match =
      Number(ar.amount) === Number(bank.amount);

    // Currency
    const currency_match =
      ar.currency === bank.currency;

    // Customer
    const customer_match =
      ar.customer === bank.customer;

    // Date with ±1 day tolerance
 // Date with ±1 day tolerance
const arDateValue = ar.transaction_date;
const bankDateValue = bank.transaction_date;

const arDate = new Date(`${arDateValue}T00:00:00Z`);
const bankDate = new Date(`${bankDateValue}T00:00:00Z`);

const differenceInDays =
  Math.abs(arDate - bankDate) / (1000 * 60 * 60 * 24);

const date_match = differenceInDays <= 1;

    const allAttributesMatch =
      amount_match &&
      currency_match &&
      customer_match &&
      date_match;

    results.push({
      json: {
        recon_key: data.recon_key,

        ar_count: arCount,
        bank_count: bankCount,

        key_match: true,

        amount_match,
        currency_match,
        customer_match,
        date_match,


        duplicate_ar: false,
        duplicate_bank: false,

        final_status: allAttributesMatch
          ? "MATCHED"
          : "EXCEPTION",

        action: allAttributesMatch
          ? ""
          : "For Investigation"
      }
    });

    continue;
  }
}

return results;

const results = [];

for (const item of items) {
  const data = item.json;

  const exceptionReasons = [];

  // Attribute discrepancies
  if (data.amount_match === false) {
    exceptionReasons.push("Amount discrepancy");
  }

  if (data.currency_match === false) {
    exceptionReasons.push("Currency discrepancy");
  }

  if (data.customer_match === false) {
    exceptionReasons.push("Customer discrepancy");
  }

  if (data.date_match === false) {
    exceptionReasons.push("Date discrepancy");
  }

  // Keep existing structural exception reason
  if (data.exception_reason) {
    exceptionReasons.push(data.exception_reason);
  }

  // Remove duplicate reason entries
  const uniqueReasons = [...new Set(exceptionReasons)];

  results.push({
    json: {
      recon_key: data.recon_key,

      ar_count: data.ar_count,
      bank_count: data.bank_count,

      key_match: data.key_match,

      amount_match: data.amount_match ?? null,
      currency_match: data.currency_match ?? null,
      customer_match: data.customer_match ?? null,
      date_match: data.date_match ?? null,

      duplicate_ar: data.duplicate_ar ?? false,
      duplicate_bank: data.duplicate_bank ?? false,

      final_status: data.final_status,

      exception_reason:
        uniqueReasons.length > 0
          ? uniqueReasons.join("; ")
          : "",

      action:
        data.final_status === "EXCEPTION"
          ? "For Investigation"
          : ""
    }
  });
}

return results;

const results = [];

for (const item of items) {
  const data = item.json;

  let expectedRule = "";
  let validationStatus = "";

  switch (data.test_scenario) {

    case "Normal match":
      expectedRule =
      data.ar_count === 1 &&
      data.bank_count === 1 &&
      data.amount_match === true &&
      data.currency_match === true &&
      data.customer_match === true &&
      data.date_match === true &&
      data.duplicate_ar === false &&
      data.duplicate_bank === false;

      validationStatus = expectedRule ? "PASS" : "REVIEW";
  break;

    case "Customer/payer discrepancy":
      expectedRule = data.customer_match === false;
      validationStatus = expectedRule ? "PASS" : "REVIEW";
      break;

    case "Currency discrepancy":
      expectedRule = data.currency_match === false;
      validationStatus = expectedRule ? "PASS" : "REVIEW";
      break;

    case "Amount discrepancy":
      expectedRule = data.amount_match === false;
      validationStatus = expectedRule ? "PASS" : "REVIEW";
      break;

    case "Missing bank transaction":
      expectedRule =
      data.ar_count > 0 &&
      data.bank_count === 0;
      validationStatus = expectedRule ? "PASS" : "REVIEW";
    break;

    case "Duplicate AR transaction":
      expectedRule = data.duplicate_ar === true;
      validationStatus = expectedRule ? "PASS" : "REVIEW";
      break;

    case "Duplicate bank transaction":
      expectedRule = data.duplicate_bank === true;
      validationStatus = expectedRule ? "PASS" : "REVIEW";
      break;

    case "Unmatched bank transaction":
      expectedRule =
      data.ar_count === 0 &&
      data.bank_count > 0;
      validationStatus = expectedRule ? "PASS" : "REVIEW";
    break;

    default:
      validationStatus = "UNKNOWN SCENARIO";
  }

  results.push({
  json: {
    ...data,
    validation_status: validationStatus,

  }
});
}

return results;

