});

const summary = {
  total_reconciliation_keys: items.length,
  matched: 0,
  exceptions: 0,
  ar_only: 0,
  bank_only: 0,
  duplicate_ar: 0,
  duplicate_bank: 0,
  duplicate_both: 0,
  amount_discrepancy: 0,
  currency_discrepancy: 0,
  customer_discrepancy: 0,
  date_discrepancy: 0
};

for (const item of items) {
  const data = item.json;

  if (data.final_status === "MATCHED") {
    summary.matched++;
  } else if (data.final_status === "EXCEPTION") {
    summary.exceptions++;
  }

  if (data.exception_reason?.includes("AR Only")) {
    summary.ar_only++;
  }

  if (data.exception_reason?.includes("Bank Only")) {
    summary.bank_only++;
  }

  if (data.exception_reason?.includes("Duplicate AR")) {
    summary.duplicate_ar++;
  }

  if (data.exception_reason?.includes("Duplicate Bank")) {
    summary.duplicate_bank++;
  }

  if (data.exception_reason?.includes("Duplicate Entry in Both")) {
    summary.duplicate_both++;
  }

  if (data.exception_reason?.includes("Amount discrepancy")) {
    summary.amount_discrepancy++;
  }

  if (data.exception_reason?.includes("Currency discrepancy")) {
    summary.currency_discrepancy++;
  }

  if (data.exception_reason?.includes("Customer discrepancy")) {
    summary.customer_discrepancy++;
  }

  if (data.exception_reason?.includes("Date discrepancy")) {
    summary.date_discrepancy++;
  }
}

return [{ json: summary }];

